-- SQLite schema for the Island Access Atlas serving layer.
-- Generated by web/scripts/build-db.ts from the prepared JSON artifacts.
-- The database is read-only at runtime. Bump user_version for breaking changes.

PRAGMA application_id = 1297105733; -- 'IAA1'
PRAGMA user_version = 1;

CREATE TABLE meta (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  schema_version INTEGER NOT NULL,
  generated_at TEXT,
  reference_day TEXT,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json))
);

CREATE TABLE islands (
  id TEXT PRIMARY KEY,
  ordinal INTEGER NOT NULL UNIQUE,
  name TEXT NOT NULL,
  atoll_code TEXT,
  atoll_name TEXT,
  lat REAL,
  lon REAL,
  population INTEGER,
  status TEXT,
  is_origin INTEGER NOT NULL CHECK (is_origin IN (0, 1)),
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  feature_json TEXT NOT NULL CHECK (json_valid(feature_json))
);
CREATE INDEX islands_atoll_idx ON islands (atoll_code);

CREATE TABLE stops (
  id TEXT PRIMARY KEY,
  ordinal INTEGER NOT NULL UNIQUE,
  code TEXT,
  name TEXT NOT NULL,
  island_id TEXT NOT NULL,
  lat REAL,
  lon REAL,
  scheduled INTEGER NOT NULL CHECK (scheduled IN (0, 1)),
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  FOREIGN KEY (island_id) REFERENCES islands (id)
);
CREATE INDEX stops_island_idx ON stops (island_id);

CREATE TABLE airports (
  id TEXT PRIMARY KEY,
  ordinal INTEGER NOT NULL UNIQUE,
  iata TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  island_id TEXT NOT NULL,
  lat REAL,
  lon REAL,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  FOREIGN KEY (island_id) REFERENCES islands (id)
);
CREATE INDEX airports_island_idx ON airports (island_id);

CREATE TABLE access_edges (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ordinal INTEGER NOT NULL UNIQUE,
  from_node TEXT NOT NULL,
  to_node TEXT NOT NULL,
  mode TEXT NOT NULL,
  minutes INTEGER NOT NULL,
  confidence TEXT,
  basis TEXT,
  distance_km REAL,
  assumed INTEGER NOT NULL CHECK (assumed IN (0, 1)),
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json))
);
CREATE INDEX access_edges_from_idx ON access_edges (from_node);
CREATE INDEX access_edges_to_idx ON access_edges (to_node);

CREATE TABLE services (
  id TEXT PRIMARY KEY,
  ordinal INTEGER NOT NULL UNIQUE,
  kind TEXT NOT NULL,
  mode TEXT NOT NULL,
  operator TEXT,
  route_id TEXT,
  route_code TEXT,
  zone TEXT,
  confidence TEXT,
  status TEXT,
  from_node TEXT,
  to_node TEXT,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json))
);
CREATE INDEX services_mode_idx ON services (mode);
CREATE INDEX services_kind_idx ON services (kind);

CREATE TABLE service_stops (
  service_id TEXT NOT NULL,
  sequence INTEGER NOT NULL,
  stop_id TEXT NOT NULL,
  arrival INTEGER NOT NULL,
  departure INTEGER NOT NULL,
  PRIMARY KEY (service_id, sequence),
  FOREIGN KEY (service_id) REFERENCES services (id) ON DELETE CASCADE,
  FOREIGN KEY (stop_id) REFERENCES stops (id)
);
CREATE INDEX service_stops_stop_idx ON service_stops (stop_id);

CREATE TABLE facilities (
  id TEXT PRIMARY KEY,
  ordinal INTEGER NOT NULL UNIQUE,
  name TEXT NOT NULL,
  island_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  tier TEXT,
  type TEXT,
  precision TEXT NOT NULL,
  source TEXT,
  source_date TEXT,
  reviewed INTEGER NOT NULL CHECK (reviewed IN (0, 1)),
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  FOREIGN KEY (island_id) REFERENCES islands (id)
);
CREATE INDEX facilities_island_idx ON facilities (island_id);
CREATE INDEX facilities_kind_idx ON facilities (kind);

CREATE TABLE categories (
  id TEXT PRIMARY KEY,
  ordinal INTEGER NOT NULL UNIQUE,
  label TEXT NOT NULL,
  kind TEXT NOT NULL,
  group_name TEXT NOT NULL,
  definition TEXT,
  confidence_note TEXT,
  source TEXT,
  facility_count INTEGER,
  island_count INTEGER,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json))
);

CREATE TABLE facility_categories (
  facility_id TEXT NOT NULL,
  category_id TEXT NOT NULL,
  PRIMARY KEY (facility_id, category_id),
  FOREIGN KEY (facility_id) REFERENCES facilities (id) ON DELETE CASCADE,
  FOREIGN KEY (category_id) REFERENCES categories (id)
);
CREATE INDEX facility_categories_category_idx ON facility_categories (category_id);

CREATE TABLE hdx_meta (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json))
);

CREATE TABLE hdx_national (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ordinal INTEGER NOT NULL UNIQUE,
  category TEXT NOT NULL,
  threshold TEXT NOT NULL,
  share REAL NOT NULL,
  population INTEGER NOT NULL,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json))
);

CREATE TABLE hdx_units (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ordinal INTEGER NOT NULL UNIQUE,
  adm_level TEXT,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  within5km REAL,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json))
);
